	}

	for _, doc := range docs {
		if agentID != "" {
			if aid, ok := doc.Metadata["agent_id"].(string); ok && aid != agentID {
				continue
			}
		}

		builder := array.NewRecordBuilder(s.allocator, schema)
		defer builder.Release()

		intent := ""
