		builder.Field(5).(*array.Float64Builder).Append(relevance)
		builder.Field(6).(*array.BooleanBuilder).Append(verified)

		record := builder.NewRecord()
		if err := writer.Write(record); err != nil {
			record.Release()
			return err
		}
		record.Release()
